\section{Introduction}

\subsection{Lattices, theta series, and modular forms}
A \emph{lattice} $L$ of rank $r$ is a discrete subgroup of $\R^r$ of full rank, equivalently the integer span of a basis $b_1, \dots, b_r$. It is \emph{integral} if $\langle u, v\rangle \in \Z$ for all $u, v \in L$, \emph{even} if $\langle v, v\rangle \in 2\Z$ for all $v$, and \emph{unimodular} if it equals its dual $L^* = \{x : \langle x, v\rangle \in \Z \ \forall v \in L\}$.

The \emph{theta series} of $L$ encodes the distribution of squared lengths:
\[
\theta_L(\tau) = \sum_{v \in L} q^{\langle v, v\rangle/2}, \qquad q = e^{2\pi i \tau}, \ \operatorname{Im}\tau > 0.
\]
For an even unimodular lattice of rank $r \equiv 0 \pmod 8$, $\theta_L$ is a modular form of weight $r/2$ for $\mathrm{SL}_2(\Z)$.

For even weight $k \ge 4$, the normalized Eisenstein series is
\[
E_k(\tau) = 1 - \frac{2k}{B_k}\sum_{n \ge 1}\sigma_{k-1}(n)\,q^n, \qquad \sigma_{s}(n) = \sum_{d \mid n} d^{s},
\]
with $B_k$ the $k$-th Bernoulli number. In particular
\[
E_4(\tau) = 1 + 240\sum_{n\ge 1}\sigma_3(n)\,q^n, \qquad E_8(\tau) = 1 + 480\sum_{n\ge 1}\sigma_7(n)\,q^n.
\]

\subsection{The rank-$8$ Siegel--Weil identity}
The space $M_4(\mathrm{SL}_2(\Z))$ is one-dimensional, spanned by $E_4$. Since $E_8$ (the lattice) is the unique even unimodular lattice of rank $8$ and $\theta_{E_8}$ is a weight-$4$ form with constant term $1$,
\[
\theta_{E_8} = E_4, \qquad\text{hence}\qquad r(n) := \#\{v \in E_8 : \langle v, v\rangle = 2n\} = 240\,\sigma_3(n).
\]
This is the foundational case of the classical Siegel--Weil formula.

\subsection{Squaring: the weight-$8$ convolution law}
The space $M_8(\mathrm{SL}_2(\Z))$ is also one-dimensional (no weight-$8$ cusp forms), so $E_4^2 = E_8$. Matching the coefficient of $q^n$ gives the convolution identity
\begin{equation}
\sigma_7(n) = \sigma_3(n) + 120\sum_{i=1}^{n-1}\sigma_3(i)\,\sigma_3(n-i), \tag{$\star$}
\end{equation}
valid for all $n \ge 1$, where $120 = 240^2/480$.

\subsection{Contribution}
We prove, independently of $(\star)$, the congruence $\sigma_7(n) \equiv \sigma_3(n) \pmod{120}$, establish that $120$ is optimal, and transport the result to lattice representation numbers.

\section{Definitions}

\begin{definition}[Divisor-power sum]
For $s \ge 0$ and $n \ge 1$, $\sigma_s(n) = \sum_{d \mid n} d^s$, the sum over positive divisors of $n$, with $\sigma_s(0) = 0$.
\end{definition}

\begin{definition}[$E_8$ representation number]
$r(n) = 240\,\sigma_3(n)$, the number of $E_8$ vectors of squared length $2n$.
\end{definition}

\begin{definition}[Weight-$8$ companion count]
$s(n) = 240\,\sigma_7(n)$.
\end{definition}

\section{Local power congruences}

\begin{lemma}[Mod $8$]\label{lem:mod8}
For every integer $d \ge 0$, $d^7 \equiv d^3 \pmod 8$.
\end{lemma}
\begin{proof}
$d^k \bmod 8$ depends only on $d \bmod 8$, so check the eight residues. If $d$ is even, $8 \mid d^3$ and $8 \mid d^7$. If $d$ is odd, $d^2 \equiv 1 \pmod 8$, hence $d^4 \equiv 1$ and $d^7 = d^3 d^4 \equiv d^3$.
\end{proof}

\begin{lemma}[Mod $3$]\label{lem:mod3}
For every integer $d \ge 0$, $d^7 \equiv d^3 \pmod 3$.
\end{lemma}
\begin{proof}
If $3 \mid d$, both sides vanish. Otherwise $d^2 \equiv 1 \pmod 3$ by Fermat, so $d^4 \equiv 1$ and $d^7 = d^3 d^4 \equiv d^3$.
\end{proof}

\begin{lemma}[Mod $5$]\label{lem:mod5}
For every integer $d \ge 0$, $d^7 \equiv d^3 \pmod 5$.
\end{lemma}
\begin{proof}
If $5 \mid d$, both sides vanish. Otherwise $d^4 \equiv 1 \pmod 5$ by Fermat, so $d^7 = d^3 d^4 \equiv d^3$.
\end{proof}

\begin{theorem}[Global power congruence]\label{thm:pow}
For every integer $d \ge 0$, $d^7 \equiv d^3 \pmod{120}$.
\end{theorem}
\begin{proof}
The moduli $8$, $3$, $5$ are pairwise coprime with product $120$. Lemmas~\ref{lem:mod3} and~\ref{lem:mod5} with the Chinese Remainder Theorem give $d^7 \equiv d^3 \pmod{15}$; combining with Lemma~\ref{lem:mod8} yields $d^7 \equiv d^3 \pmod{120}$.
\end{proof}

\section{The weight-$8$ / weight-$4$ congruence}

\begin{theorem}[The $E_4^2 = E_8$ congruence]\label{thm:main}
For every $n \ge 0$, $\sigma_7(n) \equiv \sigma_3(n) \pmod{120}$.
\end{theorem}
\begin{proof}
$\sigma_7(n) - \sigma_3(n) = \sum_{d \mid n}(d^7 - d^3)$. By Theorem~\ref{thm:pow} each summand is divisible by $120$, hence so is the sum.
\end{proof}

\begin{proposition}[Termwise dominance]\label{prop:dom}
For every $n$, $\sigma_3(n) \le \sigma_7(n)$.
\end{proposition}
\begin{proof}
For each divisor $d \ge 1$, $d^3 \le d^7$; sum over divisors.
\end{proof}

\begin{corollary}[Integral divisibility]\label{cor:dvd}
For every $n$, $120 \mid \sigma_7(n) - \sigma_3(n)$ in $\Z$, with non-negative quotient equal (under $(\star)$) to $\sum_{i=1}^{n-1}\sigma_3(i)\sigma_3(n-i)$.
\end{corollary}

\section{Optimality of the modulus}

\begin{theorem}[Sharpness]\label{thm:sharp}
The congruence of Theorem~\ref{thm:main} fails modulo $240$. Explicitly, $\sigma_7(2) - \sigma_3(2) = 129 - 9 = 120$, divisible by $120$ but not $240$.
\end{theorem}
\begin{proof}
The divisors of $2$ are $1, 2$, so $\sigma_7(2) = 1 + 128 = 129$ and $\sigma_3(2) = 1 + 8 = 9$; their difference is $120$, and $240 \nmid 120$.
\end{proof}

Thus $120 = \gcd\{\sigma_7(n) - \sigma_3(n) : n \ge 1\}$ is the exact arithmetic weight of the correction term.

\section{Transport to lattice representation numbers}

\begin{theorem}[Genus-level congruence]\label{thm:genus}
With $r(n) = 240\,\sigma_3(n)$ and $s(n) = 240\,\sigma_7(n)$, we have $28800 \mid s(n) - r(n)$, where $28800 = 240 \cdot 120$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:dvd}, $120 \mid \sigma_7(n) - \sigma_3(n)$; multiplying by $240$ gives $s(n) - r(n) = 240(\sigma_7(n) - \sigma_3(n))$, divisible by $28800$.
\end{proof}

For the two rank-$16$ even unimodular lattices $E_8 \oplus E_8$ and $D_{16}^+$, both theta series equal $E_8$ (no weight-$8$ cusp form), and Theorem~\ref{thm:genus} places their vector counts in a fixed residue class modulo $28800$ relative to $240\,\sigma_3(n)$.

\section{Algorithms}

\begin{algorithm}[Divisor-power sum]
Compute $\sigma_s(n)$ by iterating $d = 1,\dots,n$, testing $d \mid n$, accumulating $d^s$. Complexity $O(\sqrt n \log s)$ with divisor pairing.
\end{algorithm}

\begin{algorithm}[Congruence certificate]
For $n = 1,\dots,N$, verify $120 \mid \sigma_7(n) - \sigma_3(n)$ and check $(\star)$ via the self-convolution.
\end{algorithm}

\begin{algorithm}[Sharpness search]
Compute $\gcd_{1 \le n \le N}(\sigma_7(n) - \sigma_3(n))$; it stabilizes at $120$ from $n = 2$.
\end{algorithm}

\section{Discussion}
Theorem~\ref{thm:main} is a hand-checkable fingerprint of the rank-$8$ Siegel--Weil identity. The constant $120 = 8\cdot 3\cdot 5$ tracks Bernoulli-number denominators, explaining the clean split at the primes $2, 3, 5$. The elementary proof yields more than the modular identity alone: it certifies sharpness of the modulus.

\section{Future directions}
\textbf{Direction 1.} Upgrade the congruence to the equality $(\star)$, making $\sigma_7(n) - \sigma_3(n)$ a positive multiple of $120$ for $n \ge 2$.

\textbf{Direction 2.} A hierarchy $\sigma_{2k-1}(n) \equiv \sigma_3(n) \pmod{M_k}$ with optimal $M_k$ governed by Bernoulli denominators, $M_4 = 120$ being the first nontrivial case.

\textbf{Direction 3.} Representation-number congruences modulo $28800$ for all rank-$16$ even unimodular lattices, the difference being a vanishing cusp-form contribution.

\section{Conclusion}
From $\theta_{E_8} = E_4$ and $E_4^2 = E_8$ we isolated the sharp congruence $\sigma_7(n) \equiv \sigma_3(n) \pmod{120}$, proved it elementarily via local congruences and the Chinese Remainder Theorem, established optimality, and transported it to a genus-level congruence modulo $28800$.

