from typing import List

def divisors(n: int) -> List[int]:
    ds: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma(s: int, n: int) -> int:
    return 0 if n == 0 else sum(d ** s for d in divisors(n))

def e8_vector_count(n: int) -> int:
    """Number of E8 vectors of squared length 2n = 240 * sigma_3(n)."""
    return 240 * sigma(3, n)

if __name__ == "__main__":
    for n in range(1, 11):
        print(f"n={n}: sigma_3={sigma(3,n)}, r(n)={e8_vector_count(n)}")

from typing import List

def divisors(n: int) -> List[int]:
    ds: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d); ds.append(n // d)
        d += 1
    return sorted(set(ds))

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n)) if n else 0

def check_congruence(N: int) -> bool:
    """Verify sigma_7(n) == sigma_3(n) (mod 120) for n = 1..N."""
    return all((sigma(7, n) - sigma(3, n)) % 120 == 0 for n in range(1, N + 1))

def check_pointwise(D: int) -> bool:
    """Verify d^7 == d^3 (mod 120) for d = 0..D."""
    return all((d ** 7 - d ** 3) % 120 == 0 for d in range(D + 1))

if __name__ == "__main__":
    print("pointwise d^7==d^3 mod 120 (d<=500):", check_pointwise(500))
    print("sigma_7==sigma_3 mod 120 (n<=500):", check_congruence(500))

from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n)) if n else 0

def convolution(n: int) -> int:
    """Self-convolution sum_{i=1}^{n-1} sigma_3(i) sigma_3(n-i)."""
    return sum(sigma(3, i) * sigma(3, n - i) for i in range(1, n))

def predict_sigma7(n: int) -> int:
    """E4^2 = E8 law: sigma_3(n) + 120 * convolution(n)."""
    return sigma(3, n) + 120 * convolution(n)

if __name__ == "__main__":
    for n in range(1, 12):
        print(f"n={n}: sigma_7={sigma(7,n)}, predicted={predict_sigma7(n)}, "
              f"equal={sigma(7,n)==predict_sigma7(n)}")

from math import gcd
from functools import reduce
from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n)) if n else 0

def correction_gcd(N: int) -> int:
    """gcd of sigma_7(n) - sigma_3(n) over n = 1..N. Equals 120 (sharp)."""
    return reduce(gcd, (sigma(7, n) - sigma(3, n) for n in range(1, N + 1)))

if __name__ == "__main__":
    print("sigma_7(2)-sigma_3(2) =", sigma(7, 2) - sigma(3, 2))
    print("gcd of corrections up to N=300 =", correction_gcd(300))
    print("fails mod 240 at n=2:", (sigma(7, 2) - sigma(3, 2)) % 240 != 0)

