from typing import Optional

def local_ok(m: int) -> bool:
    return all((a ** 7 - a ** 3) % m == 0 for a in range(m))

def global_power_congruence() -> Optional[int]:
    # local checks at prime-power factors of 120 = 8 * 3 * 5
    assert local_ok(8) and local_ok(3) and local_ok(5)
    for d in range(120):
        if (d ** 7 - d ** 3) % 120 != 0:
            return d
    return None  # None means the congruence holds for all residues

